import {HM_RULES,hasHMRules,validateHMRules,hmNeedsQuest} from './hm-rules.js';
import {HM_RUNTIME} from './hm-runtime-code.js';
import {HM_PROFILES} from './hm-profiles.js';
import {readAuthoring,findEvent} from './authoring-model.js';
const BASE=0x08000000,ORDER=['flash','cut','fly','strength','surf','rocksmash','waterfall'];
function fingerprint(bytes){let h=2166136261;for(const n of bytes)h=Math.imul(h^n,16777619);return h>>>0;}
export function hmNativeProfile(reader,hash){const candidates=HM_PROFILES[hash]?[HM_PROFILES[hash]]:[...new Set(Object.values(HM_PROFILES))],p=candidates.find(p=>p.checks.every(c=>c.at>=0&&c.at+c.size<=reader.bytes.length&&fingerprint(reader.bytes.slice(c.at,c.at+c.size))===c.hash));if(!p)throw Error(HM_PROFILES[hash]?'A native HM hook failed source verification. No ROM was exported.':'Global HM code hooks are unsupported by the included native adapters for this ROM. Map editing and event drafts remain available.');return p;}

function branch(data,at,to){let d=to-at-4;if(d%2||d< -0x400000||d>=0x400000)throw Error('Native HM branch is out of range.');const v=new DataView(data.buffer);v.setUint16(at,0xf000|((d>>12)&2047),true);v.setUint16(at+2,0xf800|((d>>1)&2047),true);}
function cloneFunction(reader,output,start,length,label){const original=reader.bytes.slice(start,start+length),calls=[];for(let i=0;i+3<length;i+=2){const a=original[i]|original[i+1]<<8,b=original[i+2]|original[i+3]<<8;if((a&0xf800)!==0xf000||(b&0xf800)!==0xf800)continue;let d=(a&2047)<<12|(b&2047)<<1;if(d&0x400000)d-=0x800000;calls.push({at:i,to:BASE+start+i+4+d+1});i+=2;}const end=(length+3)&~3,data=new Uint8Array(end+calls.length*8),v=new DataView(data.buffer);data.set(original);for(const [i,c]of calls.entries()){const at=end+i*8;data.set([0,75,24,71],at);v.setUint32(at+4,c.to,true);branch(data,c.at,at);}return BASE+output.allocate(data,label)+1;}
function jump(output,at,to){if(at&3)throw Error('An HM hook is not word-aligned.');const data=Uint8Array.of(0,75,24,71,0,0,0,0);new DataView(data.buffer).setUint32(4,to,true);output.write(at,data);}
export function installHMRules(project,reader,hash,output,{questRuntime,itemIds=new Map(),fieldProfile}={}){
 if(!hasHMRules(project))return{reports:[],runtime:null};validateHMRules(project);const p=hmNativeProfile(reader,hash);if(project.hmRules.moves.dive)throw Error('This FireRed engine has no usable Dive field move. Leave Dive on native defaults for this export.');if(hmNeedsQuest(project)&&!questRuntime)throw Error('HM event and quest prerequisites need this source’s verified project-save runtime.');
 const alloc=(bytes,why)=>BASE+output.allocate(bytes,why),slot=id=>{const q=project.questFlags?.find(q=>q.id===id);if(!q)throw Error('An HM prerequisite is missing its saved flag.');return q.slot;},a=readAuthoring(project),rows=new Uint8Array(7*12),rv=new DataView(rows.buffer);
 for(const [i,effect]of ORDER.entries()){const h=HM_RULES[effect],r=project.hmRules.moves[effect],row=i*12;rv.setUint16(row,h.move,true);if(!r)continue;rows[row+4]=['native','party','hm','item','free','disabled'].indexOf(r.mode);let item=r.mode==='hm'?h.hmItem:r.itemRef?itemIds.get(r.itemRef):r.itemId||0;if((r.mode==='item'||r.mode==='hm')&&(!Number.isInteger(item)||item<1||item>=375))throw Error(h.name+': choose a bound native item ID below 375.');rv.setUint16(row+2,item||0,true);rows[row+5]=r.conditions.length;
  if(r.conditions.length){const data=new Uint8Array(r.conditions.length*40),v=new DataView(data.buffer);for(const [j,c]of r.conditions.entries()){const at=j*40;if(c.kind==='badge'){v.setUint16(at+2,c.badge,true);continue;}data[at]=['variable','option'].includes(c.kind)?2:1;data[at+1]=['variable','option'].includes(c.kind)?{lt:0,eq:1,gt:2,le:3,ge:4,ne:5}[c.operator]:1;v.setUint16(at+2,['variable','option'].includes(c.kind)?c.value:c.value===false?0:1,true);const slots=['variable','option'].includes(c.kind)?a.variables.find(v=>v.id===c.variableId).bitIds.map(slot):[slot(c.kind==='event'?findEvent(project,c.eventId)?.n.runtime?.completionFlag:c.flagId)];data[at+36]=slots.length;slots.forEach((n,k)=>v.setUint16(at+4+k*2,n,true));}rv.setUint32(row+8,alloc(data,'HM prerequisites: '+h.name),true);}
 }
 const checks=p.scriptSites.map(s=>[BASE+s.address,ORDER.indexOf(s.effect)]);
 const checkBytes=new Uint8Array(checks.length*8),cv=new DataView(checkBytes.buffer);checks.forEach(([at,index],i)=>{cv.setUint32(i*8,at,true);cv.setUint32(i*8+4,index,true);});
 const config={magic:0x314d4853,flagOriginal:cloneFunction(reader,output,p.flag,p.flagLength,'Preserved story flag reader'),bag:p.bag,getMon:p.getMon,knowsMove:p.knowsMove,party:p.party,flagCommand:p.flagCommand,partyCommand:p.partyCommand,result:p.result,speciesVar:p.speciesVar,var0:0x020370b8,var1:0x020370ba,questEntry:questRuntime?.entry||0,partyInternal:p.partyInternal,itemIsMail:p.itemIsMail,surfOriginal:cloneFunction(reader,output,p.surf,p.surfLength,'Preserved native Surf check'),testAvatar:p.testAvatar,partyReturn:p.partyReturn,surfReturn:p.surfReturn,waterReturn:p.waterReturn,callbacks:p.callbacks+BASE,rules:alloc(rows,'Global HM policy table'),scriptChecks:alloc(checkBytes,'Native HM badge sites'),scriptCheckCount:checks.length,varGet:p.varGet,switchVar:p.switchVar};
 const code=HM_RUNTIME,binary=Uint8Array.from(atob(code.bytes),c=>c.charCodeAt(0)),at=output.allocate(binary,'Global HM runtime'),v=new DataView(binary.buffer);for(const offset of code.relocations)v.setUint32(offset,v.getUint32(offset,true)+BASE+at,true);for(const [name,value]of Object.entries(config)){const index=code.configFields.indexOf(name);if(index<0)throw Error('Invalid HM runtime configuration field.');v.setUint32(code.symbols.hm_config+index*4,value,true);}output.write(at,binary);const fn=name=>BASE+at+(code.symbols[name]|1);
 jump(output,p.flag,fn('hm_flag'));jump(output,p.surf,fn('hm_surf'));jump(output,p.partyList,fn('hm_partylist'));output.int(p.table+43*4,fn('hm_checkflag'));output.int(p.table+124*4,fn('hm_checkparty'));
 return{reports:Object.keys(project.hmRules.moves).map(e=>'Global '+HM_RULES[e].name+': '+project.hmRules.moves[e].mode+' · '+project.hmRules.moves[e].conditions.length+' prerequisites'),runtime:{address:at,entries:Object.fromEntries(['hm_actor','hm_flag','hm_checkflag','hm_checkparty','hm_surf','hm_partylist'].map(name=>[name,fn(name)])),config}};
}
